const def = (name, dur, fn, o) => { fn.dur = dur; Object.assign(fn, o); ACT[name] = fn; return fn; };
const NF = (a) => (a.near() === 'R' ? { n: 'aR', f: 'aL', sn: 'shR', sf: 'shL', fn: 'fR', ff: 'fL' } : { n: 'aL', f: 'aR', sn: 'shL', sf: 'shR', fn: 'fL', ff: 'fR' });
